dividu daarin werkelijk heeft.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/220888/oorlog-en-vrede.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/220888/oorlog-en-vrede.html","sha256":"5d6a09a80e09e7882fe7f6335e2e29a3fe000c67dbd79af0376b3d61b1cec8e2","checkedAt":"2026-11-01T14:00:40.630Z","fact":"Hardback ISBN 9789028292086 verschijningsdatum 10/05/2019 NUR 302 Vertaalde literaire roman, novelle imprint Uitgeverij Van Oorschot uitgever Uitgeverij G.A. Van Oorschot B.V. taal Nederlands","sourceAuthors":"Leo Tolstoj , L.N. Tolstoj , Lev Tolstoj , Lev Nikolajevitsj Tolstoj , L N Tolstoj","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789025477974","key":{"isbn_13":"9789025477974"},"before":null,"after":{"work_id":45,"title":"De oude man en de zee","language":"nld","isbn_13":"9789025477974","isbn_10":null,"open_library_edition_id":null,"publisher":"Atlas Contact, Uitgeverij"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789025477974","key":{"edition_id":"@edition:9789025477974"},"before":null,"after":{"edition_id":"@edition:9789025477974","work_id":45,"bound_author_id":37,"bound_title":"De oude man en de zee","bound_language":"nld","bound_isbn13":"9789025477974","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000737783_De_oude_man_en_de_zee_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/36836/de-oude-man-en-de-zee.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/36836/de-oude-man-en-de-zee.html","sha256":"038e81660fb498964df965ff2021b9e507